mapper.select:
select d.TRADE_ID as tradeId, d.BUSI_TYPE as busiTypeCode, d.BUSI_TYPE as busiType,
acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, zc.FINPROD_ID as assetId, zc.FINPROD_ABBR as assetAbbr, zc.profit_type profitTypeCode, zc.profit_type profitType, d.PS as psCode, d.PS as ps, d.TRADE_MARKET as tradeMarketCode, d.TRADE_MARKET as tradeMarket, d.INV_AIM as invAimCode, d.INV_AIM as invAim, DATE_FORMAT(d.vdate,'%Y-%m-%d') as vDate, DATE_FORMAT(d.mDate,'%Y-%m-%d') as mDate, DATE_FORMAT(d.TRADE_DATE,'%Y-%m-%d') as tradeDate, DATE_FORMAT(d.settle_date,'%Y-%m-%d') as settleDate, DATE_FORMAT(d.cprice_Date,'%Y-%m-%d') as cpriceDate, d.CCY as ccyCode, d.CCY as ccy, d.PRIN_AMT as prinAmt, d.UNIT_CPRICE as unitCprice, d.UNIT_FPRICE as unitFprice, d.share_amt shareAmt, d.CPRICE_AMT as cpriceAmt, d.unit_INT as unitInt, d.INT_AMT as intAmt, d.FPRICE_AMT as fpriceAmt, d.FEE_AMT as feeAmt, tdf.FEE_AMT as tdFeeAmt,
( CASE WHEN d.PS='T12' THEN (d.SHARE_AMT)*(d.UNIT_CPRICE) ELSE d.TRADE_AMT END )as tradeAmt, d.YIELD*100 as yield, d.EXER_YIELD as exerYield, d.TRADE_STATUS as tradeStatusCode, d.TRADE_STATUS as tradeStatus, d.counter_id counterId,
d.is_out_trade as isOutTradeCode, d.is_out_trade as isOutTrade, d.trader trader, d.chl_id chlId, ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN DATE_FORMAT(cash.VDATE,'%Y-%m-%d') ELSE NULL END ) as interestBeginDate, ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN DATE_FORMAT(cash.MDATE,'%Y-%m-%d') ELSE NULL END ) as interestEndDate, ( CASE WHEN instr('T08,T09,T22,T23', d.ps) >0 THEN DATE_FORMAT(cash.PAY_DATE,'%Y-%m-%d') ELSE NULL END ) as planPayDate,
0.0 returnAmt from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id
left join TRD_PRODUCT_DEAL_ADD e on d.trade_id = e.trade_id
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = d.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join TRD_TRADE_FEE_DETAIL tdf on tdf.trade_id = d.trade_id and tdf.fee_type = 'B09' left join MST_CUSTOMER_INFO cust_out on cust_out.customer_id = d.counter_id left join FIN_PRODUCT cust_in on cust_in.finprod_id = d.counter_id left join FIN_CASH_PLAN cash on cash.FINPROD_ID = d.finprod_id and cash.PAY_DATE = d.TRADE_DATE where 1=1
and d.TRADE_ID = #{paTradeId}
and acct.ACCT_SUBJECT_ID = #{prodId}
and ( zc.FINPROD_ID like concat_ws('','%',#{paAsset},'%') or zc.FINPROD_ABBR like concat_ws('','%',#{paAsset},'%') ) and d.BUSI_TYPE in
#{queryType}
and d.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and d.PS in
#{paPs}
and d.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
and d.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
and zc.profit_type=#{profitType}

select A.tradeid tradeId, A.finprodid prodId, A.finprodabbr prodAbbr, A.finprodtype feeTypeName,
group_concat(a.fee_type ORDER BY a.fee_type ) feeTypeCode, A.tradedate tradeDate, sum(A.fpriceamt) tradeAmt, A.ccy ccy, A.ccyCode ccyCode, A.tradestatus tradeStatus, A.busiTypeCode busiTypeCode, A.tradestatusCode tradestatusCode, A.remark remark from ( select tpd.trade_id tradeid,
acct.ACCT_SUBJECT_ID as finprodid, acct.ACCT_SUBJECT_NAME as finprodabbr, ttfd.fee_type, case when ttfd.fee_type = 'TAX0102' or ttfd.fee_type = 'TAX0202' or ttfd.fee_type = 'TAX0302' then '增�?�税' else ttfd.fee_type end finprodtype, DATE_FORMAT(tpd.trade_date,'%Y-%m-%d') tradeDate, ttfd.fee_amt fpriceamt, tpd.ccy ccy, tpd.ccy ccyCode, tpd.trade_status tradestatus, tpd.trade_status tradestatusCode, tpd.BUSI_TYPE as busiTypeCode, '' remark from TRD_PRODUCT_DEAL tpd
LEFT JOIN TRD_PRODUCT_DEAL_ADD EXT ON TPD.TRADE_ID=EXT.TRADE_ID
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = tpd.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join TRD_TRADE_FEE_DETAIL ttfd on tpd.trade_id = ttfd.trade_id where 1=1 and tpd.finprod_type = 'C07'
and tpd.TRADE_ID like concat_ws('','%',#{paTradeId},'%')
and tpd.TRADE_ID like concat_ws('','%',#{paAsset},'%') and tpd.BUSI_TYPE in
#{queryType}
and tpd.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and tpd.PS in
#{paPs}
and tpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
and tpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
and fp.profit_type=#{profitType}
) A group by A.tradeid, A.finprodid, A.finprodabbr, A.tradedate, A.ccy, A.tradestatus, A.remark, A.finprodtype, A.busiTypeCode

select tpd.trade_id tradeId,
acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, tpd.finprod_type as feeTypeNameCode, tpd.finprod_type finprodTypeName, DATE_FORMAT(tpd.trade_date,'%Y-%m-%d') tradeDate, tpd.trade_amt tradeAmt, tpd.ccy ccy, tpd.ccy as ccyCode, tpd.BUSI_TYPE busiTypeCode, tpd.trade_status tradeStatus, tpd.trade_status as tradeStatusCode, '' remark from TRD_PRODUCT_DEAL tpd
left join TRD_PRODUCT_DEAL_ADD ext on tpd.trade_id = ext.trade_id
inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = tpd.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE where tpd.busi_type = '18' and tpd.finprod_type != 'C07'
and tpd.TRADE_ID like concat_ws('','%',#{paTradeId},'%')
and tpd.TRADE_ID like concat_ws('','%',#{paAsset},'%') and tpd.BUSI_TYPE in
#{queryType}
and tpd.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and tpd.PS in
#{paPs}
and tpd.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
and tpd.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
and fp.profit_type=#{profitType}

select T0.TRADE_ID as tradeId, acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, T0.BUSI_TYPE as busiTypeCode, T0.BUSI_TYPE as busiType,
T0.ORDER_TYPE as type, DATE_FORMAT(T0.SETTLE_DATE,'%Y-%m-%d') as settleDat, T0.SETTLE_AMT as settleAmt, T0.CCY as ccyCode, T0.CCY as ccy, (case when T0.PS = '01' then T4.ACCT_NAME else T5.ACCT_NAME end) AS myAcctName, (case when T0.PS = '01' then T0.MY_ACCT_NO else T0.COUNTER_ACCT_NO end) AS myAcctNo, (case when T0.PS = '01' then T5.ACCT_NAME else T4.ACCT_NAME end) AS counterAcctName, (case when T0.PS = '01' then T0.COUNTER_ACCT_NO else T0.MY_ACCT_NO end) AS counterAcctNo, T0.SETTLE_STATUS AS status from STL_ORDERS T0 left join TRD_PRODUCT_DEAL T1 on T0.TRADE_ID = T1.TRADE_ID inner join BOK_DEAL_ACCOUNTING deal on ( deal.BUSI_NO = T1.TRADE_ID OR deal.BUSI_NO = T0.ORDER_ID ) inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE left join STL_CAPACCT_INFO T4 on T0.MY_ACCT_NO = T4.ACCT_NO left join STL_CAPACCT_INFO T5 on T0.COUNTER_ACCT_NO = T5.ACCT_NO where 1=1 and ORDER_TYPE in ('1001', '1002', '1007', '1008','1009', '1010')
and T0.TRADE_ID like concat_ws('','%',#{paTradeId},'%')
and T1.TRADE_ID like concat_ws('','%',#{paAsset},'%') and T0.BUSI_TYPE in
#{queryType}
and (T0.BUSI_TYPE in
#{paBusiType}
or '19' in
#{paBusiType}
)
and book.BOOKSET_ID in
#{bookSetId}
and T0.PS in
#{paPs}
and T0.SETTLE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
and T0.SETTLE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
order by T0.TRADE_ID

select d.TRADE_ID as tradeId, d.BUSI_TYPE as busiTypeCode, d.BUSI_TYPE as busiType, acct.ACCT_SUBJECT_ID as prodId, acct.ACCT_SUBJECT_NAME as prodAbbr, zc.FINPROD_ID as assetId, zc.FINPROD_ABBR as assetAbbr, d.PS as psCode, d.PS as ps, d.TRADE_MARKET as tradeMarketCode, d.TRADE_MARKET as tradeMarket, d.INV_AIM as invAimCode, d.INV_AIM as invAim, DATE_FORMAT(d.TRADE_DATE,'%Y-%m-%d') as tradeDate, d.CCY as ccyCode, d.CCY as ccy, d.PRIN_AMT as prinAmt, d.INT_AMT as intAmt, d.TRADE_AMT as tradeAmt, d.TRADE_STATUS as tradeStatusCode, d.TRADE_STATUS as tradeStatus from trd_PRODUCT_DEAL d inner join FIN_PRODUCT zc on zc.finprod_id = d.finprod_id inner join BOK_DEAL_ACCOUNTING deal on deal.BUSI_NO = d.TRADE_ID inner join BOK_BOOKSET book on deal.BOOKSET_ID = book.BOOKSET_ID inner join BOK_ACCT_SUBJECT_INFO acct on acct.ACCT_SUBJECT_ID = book.ACCT_SUBJECT_ID and acct.ACCT_SUBJECT_TYPE = book.ACCT_SUBJECT_TYPE where 1=1
and d.TRADE_ID like concat_ws('','%',#{paTradeId},'%')
and ( zc.FINPROD_ID like concat_ws('','%',#{paAsset},'%') or zc.FINPROD_ABBR like concat_ws('','%',#{paAsset},'%') )
and d.BUSI_TYPE in
#{queryType}
and d.BUSI_TYPE in
#{paBusiType}
and book.BOOKSET_ID in
#{bookSetId}
and d.PS in
#{paPs}
and d.TRADE_DATE >= STR_TO_DATE(#{tradeDateBegin},'%Y-%m-%d')
and d.TRADE_DATE <= STR_TO_DATE(#{tradeDateEnd},'%Y-%m-%d')
and zc.profit_type=#{profitType}
